#include "editor.hpp"
#include <SDL3/SDL_opengl.h>
namespace touch::ui {
void Editor::preview(){auto size=ImGui::GetWindowSize();auto at=ImGui::GetWindowPos();auto draw=ImGui::GetWindowDrawList();draw->AddRectFilled(at,{at.x+size.x,at.y+size.y},theme::rgb(0x101010));auto frame=monitor.frame;if(frame&&frame->type==Signal::Video&&services.window){if(!texture){glGenTextures(1,&texture);glBindTexture(GL_TEXTURE_2D,texture);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);}if(uploaded!=frame){glBindTexture(GL_TEXTURE_2D,texture);if(!uploaded||uploaded->width!=frame->width||uploaded->height!=frame->height)glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA32F,frame->width,frame->height,0,GL_RGBA,GL_FLOAT,frame->values.data());else glTexSubImage2D(GL_TEXTURE_2D,0,0,0,frame->width,frame->height,GL_RGBA,GL_FLOAT,frame->values.data());uploaded=frame;}float scale=std::min(size.x/frame->width,size.y/frame->height);ImVec2 image{frame->width*scale,frame->height*scale},pos{at.x+(size.x-image.x)/2,at.y+(size.y-image.y)/2};draw->AddRectFilled(pos,{pos.x+image.x,pos.y+image.y},background==1?theme::rgb(0xdcdcdc):theme::rgb(0x191919));if(background==2)for(int y=0;y<int(image.y);y+=12)for(int x=0;x<int(image.x);x+=12)if((x/12+y/12)%2)draw->AddRectFilled({pos.x+x,pos.y+y},{pos.x+std::min(float(x+12),image.x),pos.y+std::min(float(y+12),image.y)},theme::rgb(0x646464));draw->AddImage(ImTextureID(texture),pos,{pos.x+image.x,pos.y+image.y});}else{std::string text=services.runtime.running()?"Connect or pin a TOP":"Run to preview";theme::pixel_text(draw,{at.x+(size.x-text.size()*6)/2,at.y+(size.y-7)/2},text,theme::muted,size.x);}ImGui::Dummy(size);}
}
